def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    size = len(alphabet)
    char_index = {char: i for i, char in enumerate(alphabet)}

    transitions = [[-1] * size]
    failure = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            c = char_index[char]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    queue = deque()
    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    states = [state for state in range(len(transitions)) if not terminal[state]]
    index = {state: i for i, state in enumerate(states)}
    count = len(states)

    matrix = [[0] * count for _ in range(count)]
    for state in states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * count
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    row = matrix[i]
                    for j in range(count):
                        result[j] += value * row[j]
            vector = [value % MOD for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                result_row = squared[i]
                for k, value in enumerate(matrix[i]):
                    if value:
                        row = matrix[k]
                        for j in range(count):
                            result_row[j] += value * row[j]
                for j in range(count):
                    result_row[j] %= MOD
            matrix = squared

    return sum(vector) % MOD
